import {
  PDFDocument, PDFHexString, PDFName, PDFString, StandardFonts, degrees,
  fill, popGraphicsState, pushGraphicsState, rectangle, setFillingRgbColor,
  setGraphicsState,
} from "pdf-lib";

export const NATIVE_FIXTURE_TEXT = "Web Ink preserves native PDF notes while adding new annotated passages.";
export const NATIVE_FIXTURE_ANNOTATION_COUNT = 5;
export const NATIVE_FIXTURE_NOTES = {
  highlight: "原文件高亮 🟩\n保留自定义外观",
  square: "原文件区域框",
  text: "原文件便签 📝\n第二行",
  reply: "原文件回复：继续讨论",
};

/** Original synthetic data only; no personal PDFs or reader-generated bytes. */
export async function createNativePdfFixture(pageCount = 4): Promise<Uint8Array> {
  const document = await PDFDocument.create({ updateMetadata: false });
  const font = await document.embedFont(StandardFonts.Helvetica);
  const sizes = [[600, 800], [720, 540], [420, 660], [840, 620]] as const;
  for (let index = 0; index < pageCount; index++) {
    const [width, height] = sizes[index % sizes.length]!;
    const page = document.addPage([width, height]);
    page.setCropBox(20, 30, width - 40, height - 60);
    page.setRotation(degrees((index % 4) * 90));
    page.drawText(NATIVE_FIXTURE_TEXT, { x: 50, y: height - 90, size: 12, font });
    page.drawText("A second line supports a multiline highlight and a Unicode note.", {
      x: 50, y: height - 112, size: 12, font,
    });
    page.drawText(`Synthetic page ${index + 1}; ordinary selectable text.`, {
      x: 50, y: height - 145, size: 12, font,
    });
  }
  const page = document.getPage(0), context = document.context;
  const appearance = context.register(context.formXObject([
    pushGraphicsState(), setGraphicsState("OriginalStyle"),
    setFillingRgbColor(0.2, 0.85, 0.45), rectangle(0, 0, 300, 17), fill(),
    popGraphicsState(),
  ], {
    BBox: [0, 0, 300, 17], Matrix: [1, 0, 0, 1, 0, 0],
    Resources: { ExtGState: { OriginalStyle: { Type: "ExtGState", ca: 0.33, BM: "Multiply" } } },
  }));
  const common = {
    Type: "Annot", P: page.ref, F: 4,
    CreationDate: PDFString.of("D:20260102123456Z"),
    M: PDFString.of("D:20260103123456Z"),
    T: PDFHexString.fromText("Synthetic author"),
  };
  const highlight = context.register(context.obj({
    ...common, Subtype: "Highlight", NM: PDFHexString.fromText("original-highlight"),
    Rect: [50, 640, 350, 657], QuadPoints: [50, 657, 350, 657, 50, 640, 350, 640],
    C: [0.2, 0.85, 0.45], CA: 0.33, AP: { N: appearance },
    Contents: PDFHexString.fromText(NATIVE_FIXTURE_NOTES.highlight),
  }));
  const square = context.register(context.obj({
    ...common, Subtype: "Square", NM: PDFHexString.fromText("original-square"),
    Rect: [360, 400, 470, 470], C: [1, 0, 0], BS: { Type: "Border", W: 3, S: "S" },
    Contents: PDFHexString.fromText(NATIVE_FIXTURE_NOTES.square),
  }));
  const text = context.obj({
    ...common, Subtype: "Text", NM: PDFHexString.fromText("original-text"),
    Rect: [490, 620, 510, 640], C: [1, 1, 0], Name: "Note",
    Contents: PDFHexString.fromText(NATIVE_FIXTURE_NOTES.text),
  });
  const textRef = context.register(text);
  const popup = context.register(context.obj({
    Type: "Annot", Subtype: "Popup", P: page.ref, Parent: textRef,
    Rect: [350, 500, 550, 600], Open: false, F: 4,
  }));
  text.set(PDFName.of("Popup"), popup);
  const reply = context.register(context.obj({
    ...common, Subtype: "Text", NM: PDFHexString.fromText("original-reply"),
    Rect: [490, 580, 510, 600], C: [0, 0, 1], Name: "Comment", IRT: textRef, RT: "R",
    Contents: PDFHexString.fromText(NATIVE_FIXTURE_NOTES.reply),
  }));
  for (const annotation of [highlight, square, textRef, popup, reply]) page.node.addAnnot(annotation);
  return document.save({ useObjectStreams: true, updateFieldAppearances: false });
}
